//! 🧫️ Neutral original typed receiving laws compare the independent JSON binding.
use semio_framework_dsl_record::{FieldValue,RecordValue,receiving::{self,owned,OwnedSlot}};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,ValueRefusalKind,retirement::RetireOwned};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use std::cell::Cell;
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/🫴️receiving/🔣️.json")).unwrap()}
fn grant()->RetainedCloneGrant{static POLICY:std::sync::OnceLock<RetainedCloneGrant>=std::sync::OnceLock::new();*POLICY.get_or_init(||{let value=fixture();let value=&value["grant"];RetainedCloneGrant{maximum_items:value["items"].as_u64().unwrap()as usize,maximum_copy_bytes:value["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:value["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:value["depth"].as_u64().unwrap()as usize}})}
#[derive(Debug,PartialEq,serde::Deserialize,semio_framework_dsl_record_derive::DslRecord,semio_framework_dsl_record_derive::DslReceiving,semio_framework_value::RetireOwned)]
#[serde(deny_unknown_fields)]
struct OriginalRecord{text:String,items:Vec<String>,optional:Option<String>}
#[test]
fn original_typed_receiving_generated_record_matches_serde(){
 let fixture=fixture();let expected:OriginalRecord=serde_json::from_value(serde_json::json!({"text":fixture["text"],"items":fixture["items"],"optional":fixture["optional"]})).unwrap();let mut source=Some(FieldValue::Record(expected.__dsl_to_record()));let mut observer=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut observer);let(mut output,progress)=receive_owned::<OriginalRecord>(&mut source,&mut native);assert_eq!(output.value.as_ref().unwrap(),&expected);assert!(progress.retained_capacity_bytes>0);assert_eq!(native.owned_bytes(),progress.retained_capacity_bytes);close_owned(&mut output);
}
#[test]
fn original_typed_receiving_matches_serde_and_original_ledger(){
 let fixture=fixture();let expected:Vec<String>=serde_json::from_value(fixture["items"].clone()).unwrap();let mut source=Some(FieldValue::List(expected.iter().cloned().map(FieldValue::Text).collect()));let calls=Cell::new(0);let mut observer=|_|{calls.set(calls.get()+1);true};let mut native=NativeDecodeControl::new(1<<24,&mut observer);let(mut output,progress)=receive_owned::<Vec<String>>(&mut source,&mut native);assert_eq!(output.value.as_ref().unwrap(),&expected);assert!(progress.copied_items>expected.len());assert_eq!(native.owned_bytes(),progress.retained_capacity_bytes);assert!(calls.get()>expected.len());close_owned(&mut output);
}
#[test]
fn original_typed_receiving_cancellation_retains_partial_fields_until_paid_close(){
 use owned::{DslOwnedReceivingField,OwnedFieldReceiving};let fixture=fixture();let text=fixture["text"].as_str().unwrap();let mut source=Some(FieldValue::List(vec![FieldValue::Text(text.to_owned()),FieldValue::Text(text.to_owned())]));let turn=Cell::new(0);let mut observer=|_|{let current=turn.get();turn.set(current+1);current<9};let mut native=NativeDecodeControl::new(1<<24,&mut observer);let mut cursor=<Vec<String> as DslOwnedReceivingField>::Cursor::default();let phase=one_item();let mut failure=None;for _ in 0..grant().maximum_items{match cursor.step(&mut source,&mut native,one_item().maximum_copy_bytes,phase){Ok(progress)=>assert!(progress.fits(phase)),Err(error)=>{failure=Some(error);break}}}assert_eq!(failure.unwrap().kind,ValueRefusalKind::Canceled);assert!(!cursor.terminal_is_empty());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(Default::default()));assert_eq!(result.unwrap(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for _ in 0..grant().maximum_items{if cursor.terminal_is_empty(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(phase));let progress=result.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes))}assert!(cursor.terminal_is_empty());
}

fn one_item()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,..grant()}}
fn receive_owned<T:owned::DslOwnedReceivingField>(source:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>)->(OwnedSlot<T>,RetainedCloneProgress){use owned::OwnedFieldReceiving;let phase=one_item();let mut cursor=T::Cursor::default();let mut posted=RetainedCloneProgress::default();for _ in 0..grant().maximum_items{if cursor.is_ready(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(source,native,phase.maximum_copy_bytes,phase));let progress=result.unwrap();assert!(progress.fits(phase));posted=posted.checked_add(progress).unwrap();assert!(posted.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes))}assert!(cursor.is_ready());let mut output=OwnedSlot::default();native.checkpoint().unwrap();let progress=cursor.take_into(&mut output.value,phase).unwrap();posted=posted.checked_add(progress).unwrap();assert!(posted.fits(grant()));assert!(cursor.terminal_is_empty());(output,posted)}
fn close_owned<T:RetireOwned>(owner:&mut OwnedSlot<T>){for _ in 0..grant().maximum_items{if owner.terminal_is_empty(){return}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(one_item()));let progress=result.unwrap();assert!(progress.fits(one_item()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes))}panic!("original owned field retirement exceeded its independent finite turn bound")}

#[test]
fn original_typed_receiving_owned_text_and_bytes_move_only_admitted_metadata(){
 use owned::{DslOwnedReceivingField,OwnedFieldReceiving};
 let fixture=fixture();for row in fixture["ownedCases"].as_array().unwrap().iter().filter(|row|row["kind"]!="list"){
  let phase=RetainedCloneGrant{maximum_items:row["items"].as_u64().unwrap()as usize,maximum_capacity_bytes:row["capacityBytes"].as_u64().unwrap()as usize,..one_item()};let calls=Cell::new(0);let mut observe=|_|{calls.set(calls.get()+1);true};let mut native=NativeDecodeControl::new(1<<24,&mut observe);
  if row["kind"]=="text"{let mut source=Some(FieldValue::Text(fixture["text"].as_str().unwrap().to_owned()));let Some(FieldValue::Text(text))=source.as_ref()else{unreachable!()};let pointer=text.as_ptr();let mut cursor=<String as DslOwnedReceivingField>::Cursor::default();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(&mut source,&mut native,one_item().maximum_copy_bytes,phase));let progress=result.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cursor.is_ready(),row["ready"].as_bool().unwrap());assert_eq!(source.is_some(),row["sourceSame"].as_bool().unwrap());if cursor.is_ready(){let mut output=OwnedSlot::<String>::default();cursor.take_into(&mut output.value,one_item()).unwrap();assert_eq!(output.value.as_ref().unwrap().as_ptr(),pointer);assert_eq!(output.value.as_ref().unwrap(),fixture["text"].as_str().unwrap());close_owned(&mut output);assert_eq!(calls.get(),1)}else{assert_eq!(progress,Default::default());assert_eq!(calls.get(),0);let mut input=OwnedSlot::default();*input.value=source.take();close_owned(&mut input)}assert!(cursor.terminal_is_empty())
  }else{let bytes=vec![0,127,255];let pointer=bytes.as_ptr();let mut source=Some(FieldValue::Bytes64(bytes));let mut cursor=<Vec<u8> as DslOwnedReceivingField>::Cursor::default();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(&mut source,&mut native,one_item().maximum_copy_bytes,phase));let progress=result.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(progress.fits(phase));assert!(cursor.is_ready());assert!(source.is_none());let mut output=OwnedSlot::<Vec<u8>>::default();cursor.take_into(&mut output.value,one_item()).unwrap();assert_eq!(output.value.as_ref().unwrap().as_ptr(),pointer);assert_eq!(output.value.as_ref().unwrap(),&[0,127,255]);close_owned(&mut output);assert!(cursor.terminal_is_empty())}
 }
}

#[test]
fn original_typed_receiving_owned_vector_and_generated_record_resume_one_item(){
 use owned::{DslOwnedReceivingField,OwnedFieldReceiving};let fixture=fixture();let expected:Vec<String>=serde_json::from_value(fixture["items"].clone()).unwrap();let mut source=Some(FieldValue::List(expected.iter().cloned().map(FieldValue::Text).collect()));let Some(FieldValue::List(values))=source.as_ref()else{unreachable!()};let pointers=values.iter().map(|value|{let FieldValue::Text(text)=value else{unreachable!()};text.as_ptr()}).collect::<Vec<_>>();let mut cursor=<Vec<String> as DslOwnedReceivingField>::Cursor::default();let mut callback=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut callback);let denied=RetainedCloneGrant{maximum_capacity_bytes:0,..one_item()};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(&mut source,&mut native,one_item().maximum_copy_bytes,denied));assert_eq!(result.unwrap(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(source.is_some());
 for _ in 0..grant().maximum_items{if cursor.is_ready(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(&mut source,&mut native,one_item().maximum_copy_bytes,one_item()));let progress=result.unwrap();assert!(progress.fits(one_item()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes))}assert!(cursor.is_ready());let mut output=OwnedSlot::<Vec<String>>::default();cursor.take_into(&mut output.value,one_item()).unwrap();assert_eq!(output.value.as_ref().unwrap(),&expected);assert_eq!(output.value.as_ref().unwrap().iter().map(|text|text.as_ptr()).collect::<Vec<_>>(),pointers);close_owned(&mut output);assert!(cursor.terminal_is_empty());
 let expected:OriginalRecord=serde_json::from_value(serde_json::json!({"text":fixture["text"],"items":fixture["items"],"optional":fixture["optional"]})).unwrap();let record=expected.__dsl_to_record();let FieldValue::Text(text)=record.get(0).unwrap()else{unreachable!()};let pointer=text.as_ptr();let mut source=Some(FieldValue::Record(record));let mut cursor=<OriginalRecord as DslOwnedReceivingField>::Cursor::default();for _ in 0..grant().maximum_items{if cursor.is_ready(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(&mut source,&mut native,one_item().maximum_copy_bytes,one_item()));let progress=result.unwrap();assert!(progress.fits(one_item()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes))}assert!(cursor.is_ready());let mut output=OwnedSlot::<OriginalRecord>::default();cursor.take_into(&mut output.value,one_item()).unwrap();assert_eq!(output.value.as_ref().unwrap(),&expected);assert_eq!(output.value.as_ref().unwrap().text.as_ptr(),pointer);close_owned(&mut output);assert!(cursor.terminal_is_empty());
}

#[test]
fn original_typed_receiving_owned_cancellation_retains_partial_cursor_until_paid_close(){
 use owned::{DslOwnedReceivingField,OwnedFieldReceiving};let fixture=fixture();let expected:OriginalRecord=serde_json::from_value(serde_json::json!({"text":fixture["text"],"items":fixture["items"],"optional":fixture["optional"]})).unwrap();let mut source=Some(FieldValue::Record(expected.__dsl_to_record()));let calls=Cell::new(0);let mut callback=|_|{let call=calls.get();calls.set(call+1);call<9};let mut native=NativeDecodeControl::new(1<<24,&mut callback);let mut cursor=<OriginalRecord as DslOwnedReceivingField>::Cursor::default();let mut failure=None;
 for _ in 0..grant().maximum_items{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(&mut source,&mut native,one_item().maximum_copy_bytes,one_item()));match result{Ok(progress)=>{assert!(progress.fits(one_item()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes))},Err(error)=>{assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));failure=Some(error);break}}}assert_eq!(failure.unwrap().kind,ValueRefusalKind::Canceled);assert!(!cursor.is_ready());assert!(!cursor.terminal_is_empty());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(Default::default()));assert_eq!(result.unwrap(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!cursor.terminal_is_empty());
 for _ in 0..grant().maximum_items{if cursor.terminal_is_empty(){break}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(one_item()));let progress=result.unwrap();assert!(progress.fits(one_item()));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes))}assert!(cursor.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(cursor));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if source.is_some(){let mut owner=OwnedSlot::default();*owner.value=source.take();close_owned(&mut owner)}assert_eq!(calls.get(),10);
}

#[derive(Debug,PartialEq,semio_framework_dsl_record_derive::DslRecord,semio_framework_dsl_record_derive::DslReceiving,semio_framework_value::RetireOwned)]
struct OpaqueRecord{payload:semio_framework_value::DslValue}
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct OpaqueOracle{payload:serde_json::Value}
#[derive(Debug,PartialEq,semio_framework_dsl_record_derive::DslRecord,semio_framework_dsl_record_derive::DslReceiving,semio_framework_value::RetireOwned)]
struct SkippedRecord{value:String,#[dsl(skip)]ephemeral:Option<String>}
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct SkippedOracle{value:String}
#[test]
fn original_typed_receiving_owned_declared_records_refuse_unknown_and_missing_fields_before_donation(){
 use owned::{DslOwnedReceivingField,OwnedFieldReceiving};
 for row in fixture()["shapeCases"].as_array().unwrap(){let declared=row["declarations"].as_array().unwrap().iter().map(|value|(value[0].as_u64().unwrap()as u16,value[1].as_bool().unwrap())).collect::<Vec<_>>();let mut original=OwnedSlot::<FieldValue>::default();let mut record=RecordValue::default();for value in row["fields"].as_array().unwrap(){record.fields.insert(value[0].as_u64().unwrap()as u16,if value[1].as_bool().unwrap(){FieldValue::Text("rich retained source".into())}else{FieldValue::Absent});}let capacity=record.fields.capacity();*original.value=Some(FieldValue::Record(record));let mut shape=owned::DeclaredRecordShape::default();let calls=Cell::new(0);let mut callback=|_|{calls.set(calls.get()+1);true};let mut native=NativeDecodeControl::new(1<<24,&mut callback);let mut work=0;let mut refused=false;for turn in row["turns"].as_array().unwrap(){let phase=RetainedCloneGrant{maximum_items:turn.as_u64().unwrap()as usize,maximum_copy_bytes:0,..one_item()};let Some(FieldValue::Record(record))=original.value.as_ref()else{unreachable!()};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||shape.step(record,&declared,&mut native,phase));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));match result{Ok(progress)=>{assert!(progress.fits(phase));work+=progress.copied_items;},Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert!(error.retained_progress().fits(phase));work+=error.retained_progress().copied_items;refused=true;break}}assert_eq!(record.fields.capacity(),capacity);}assert_eq!(work,row["work"].as_u64().unwrap()as usize);assert_eq!(shape.is_ready(),row["ready"].as_bool().unwrap());assert_eq!(refused,row["refused"].as_bool().unwrap());if work==0{assert_eq!(calls.get(),0)}close_owned(&mut original);}
 fn dynamic(value:&serde_json::Value)->semio_framework_value::DslValue{use semio_framework_value::{DslValue,Number};match value{serde_json::Value::Null=>DslValue::Null,serde_json::Value::Bool(value)=>DslValue::Bool(*value),serde_json::Value::Number(value)=>DslValue::Number(Number::Int(value.as_i64().unwrap())),serde_json::Value::String(value)=>DslValue::String(value.clone()),serde_json::Value::Array(values)=>DslValue::Array(values.iter().map(dynamic).collect()),serde_json::Value::Object(values)=>DslValue::Object(values.iter().map(|(key,value)|(key.clone(),dynamic(value))).collect())}}
 fn exercise<T:owned::DslOwnedReceivingField+std::fmt::Debug+PartialEq>(record:RecordValue,expected:Option<T>,pointer:fn(&T)->usize){let capacity=record.fields.capacity();let original_pointer=record.get(0).map(|value|match value{FieldValue::Text(value)=>value.as_ptr()as usize,FieldValue::Value(semio_framework_value::DslValue::Object(values))=>values.as_ptr()as usize,_=>0});let mut source=Some(FieldValue::Record(record));let calls=Cell::new(0);let mut callback=|_|{calls.set(calls.get()+1);true};let mut native=NativeDecodeControl::new(1<<24,&mut callback);let mut cursor=T::Cursor::default();let phase=one_item();
  let(result,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(&mut source,&mut native,one_item().maximum_copy_bytes,RetainedCloneGrant{maximum_items:0,..phase}));assert_eq!(result.unwrap(),Default::default());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(calls.get(),0);assert!(source.is_some());let mut refused=false;
  for _ in 0..grant().maximum_items{if cursor.is_ready(){break}let(result,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(&mut source,&mut native,one_item().maximum_copy_bytes,phase));match result{Ok(progress)=>{assert!(progress.fits(phase));assert_eq!((physical.requested_bytes,physical.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));},Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(error.retained_progress().fits(phase));refused=true;break}}}
  assert_eq!(refused,expected.is_none());if let Some(expected)=expected{assert!(cursor.is_ready());let mut output=OwnedSlot::<T>::default();cursor.take_into(&mut output.value,phase).unwrap();assert_eq!(output.value.as_ref().unwrap(),&expected);assert_eq!(pointer(output.value.as_ref().unwrap()),original_pointer.unwrap());close_owned(&mut output);}else{let Some(FieldValue::Record(record))=source.as_ref()else{panic!("refused original record stays at receiving entrance")};assert_eq!(record.fields.capacity(),capacity);assert_eq!(record.get(0).map(|value|match value{FieldValue::Text(value)=>value.as_ptr()as usize,FieldValue::Value(semio_framework_value::DslValue::Object(values))=>values.as_ptr()as usize,_=>0}),original_pointer);assert!(cursor.terminal_is_empty());}
  for _ in 0..grant().maximum_items{if cursor.terminal_is_empty(){break}let(result,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(phase));let progress=result.unwrap();assert_eq!((physical.requested_bytes,physical.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));}assert!(cursor.terminal_is_empty());let mut original=OwnedSlot::default();*original.value=source;close_owned(&mut original);
 }
 for row in fixture()["declaredCases"].as_array().unwrap(){let accepted=row["accepted"].as_bool().unwrap();let raw=&row["source"];let mut record=RecordValue::default();match row["kind"].as_str().unwrap(){
  "normal"=>{if let Some(value)=raw.get("text"){record.fields.insert(0,FieldValue::Text(value.as_str().unwrap().into()));}if let Some(value)=raw.get("items"){record.fields.insert(1,FieldValue::List(value.as_array().unwrap().iter().map(|value|FieldValue::Text(value.as_str().unwrap().into())).collect()));}if let Some(value)=raw.get("optional"){record.fields.insert(2,if value.is_null(){FieldValue::Absent}else{FieldValue::Text(value.as_str().unwrap().into())});}if let Some(value)=raw.get("undeclared"){record.fields.insert(99,FieldValue::Value(dynamic(value)));}let expected=serde_json::from_value::<OriginalRecord>(raw.clone()).ok();assert_eq!(expected.is_some(),accepted);exercise(record,expected,|value|value.text.as_ptr()as usize);},
  "opaque"=>{if let Some(value)=raw.get("payload"){record.fields.insert(0,FieldValue::Value(dynamic(value)));}if let Some(value)=raw.get("undeclared"){record.fields.insert(99,FieldValue::Value(dynamic(value)));}let oracle=serde_json::from_value::<OpaqueOracle>(raw.clone()).ok();assert_eq!(oracle.is_some(),accepted);let expected=oracle.map(|oracle|{assert_eq!(&oracle.payload,&raw["payload"]);OpaqueRecord{payload:dynamic(&oracle.payload)}});exercise(record,expected,|value|{let semio_framework_value::DslValue::Object(values)=&value.payload else{unreachable!()};values.as_ptr()as usize});},
  "skipped"=>{if let Some(value)=raw.get("value"){record.fields.insert(0,FieldValue::Text(value.as_str().unwrap().into()));}if let Some(value)=raw.get("ephemeral"){record.fields.insert(1,FieldValue::Text(value.as_str().unwrap().into()));}let oracle=serde_json::from_value::<SkippedOracle>(raw.clone()).ok();assert_eq!(oracle.is_some(),accepted);exercise(record,oracle.map(|value|SkippedRecord{value:value.value,ephemeral:None}),|value|value.value.as_ptr()as usize);},
  _=>panic!("closed original record corpus kind")
 }}
}

#[test]
fn original_owned_slot_first_close_defers_its_real_retirement_birth(){
 let mut owner=OwnedSlot::<String>::default();*owner.value=Some("original retained source".repeat(4));let pointer=owner.value.as_ref().unwrap().as_ptr();let demand=owner.close_demands(4096).unwrap();assert_eq!(demand.capacity_bytes,0);let initial=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:demand.depth};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(initial));let progress=result.unwrap();assert!(progress.fits(initial));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!owner.terminal_is_empty());let birth=owner.close_demands(4096).unwrap();assert!(birth.capacity_bytes>0);let denied=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:birth.copy_bytes,maximum_capacity_bytes:birth.capacity_bytes-1,maximum_release_bytes:birth.release_bytes,maximum_depth:birth.depth};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(denied));assert_eq!(result.unwrap(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!pointer.is_null());close_owned(&mut owner);
}

#[cfg(test)]
#[global_allocator]
static TEST_ALLOCATION_OBSERVER: semio_framework_trace_memory_testing::RequestedAllocator = semio_framework_trace_memory_testing::RequestedAllocator;
